/** Production native binding, protected SQLite, export journal and coordinator.
 * Generated WAV/in-memory token/Drive only. No actual OAuth, dot, STT or writer/CAS. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk=[35],shadows=[ShadowTextKeys::class,ShadowTextAtomicFile::class])
@SQLiteMode(SQLiteMode.Mode.NATIVE)
class DriveAForegroundLocalTest:ProtectedTextHostTestBase() {
    private lateinit var context:Context;private lateinit var scoped:AccountStorageContext
    private lateinit var session:GoogleConnectionSession;private lateinit var settings:SecureSettings
    private lateinit var keys:SyntheticPilotIntegrationTest.HostKeys;private lateinit var source:GeneralLocalStoreTest.Source
    private lateinit var drive:GoogleConnectionRegressionTest.FakeDrive
    private var recording="";private var request="";private var job="";private var result=""
    private class Memory:GoogleConnectionSession.Persistence {var value=JSONObject();override fun read()=JSONObject(value.toString());override fun write(v:JSONObject){value=JSONObject(v.toString())}}
    private lateinit var memory:Memory
    private fun activate(owner:String="PUBLIC_DRIVE_A_OWNER"){val e=session.begin();session.activate(e,"drive-a@example.invalid","drive-a@example.invalid",owner,"PUBLIC_FIXTURE_RAM_TOKEN")}
    @Before fun setup()=runBlocking(Dispatchers.IO) {
        context=RuntimeEnvironment.getApplication();memory=Memory();session=GoogleConnectionSession(memory);activate()
        scoped=AccountStorageContext(context,session.ownerBinding());keys=SyntheticPilotIntegrationTest.HostKeys()
        source=GeneralLocalStoreTest.Source().apply{put()};drive=GoogleConnectionRegressionTest.FakeDrive()
        val k=SecretKeySpec(ByteArray(32){0x29},"AES");settings=SecureSettings(scoped,object:SecureSettings.KeyAccess {override fun existing()=k;override fun createForFirstEmptyStore()=k})
        settings.update{it.put("treeUri",source.rootUri)}
        GeneralLocalStoreTest.host(scoped,keys).use{s->s.initializeEmpty();s.importSelected(source);val r=s.snapshot().getJSONObject(0);recording=r.getString("file_id");s.edit(recording,r,"PUBLIC_DRIVE_A_DONE\n\"LF 유지\"","done")}
        SyntheticApprovedSource.approve(settings,session,source,source.documents.getValue("one"),true)
    }
    private fun db()=AndroidSqlPort(scoped,GeneralLocalStore.DATABASE,scoped.assets.open("call_core_schema.sql"))
    private fun primary()=TextStoreTestSupport.open(scoped,GeneralLocalStore.DATABASE)
    private fun journal()=TextStoreTestSupport.open(scoped,DriveAExportJournal.DATABASE)
    private fun count(table:String)=db().use{it.query("SELECT COUNT(*) AS n FROM $table").single()["n"] as Long}
    private fun snap()=RecordingWorkflowStore(scoped).use{it.snapshot(recording)}
    private fun pipeline(remote:DriveTransport=drive,capable:Boolean=true)=GoogleNativePipeline(context,session,settings,{source},remote,
        postingCapability=if(capable)({_->true})else FrozenDotCapability(context)::supports){GeneralLocalStoreTest.host(it,keys)}
    private inner class NativePort(private val p:GoogleNativePipeline):RecordingAnalysisPort {
        override val requiresNativeBinding=true
        override fun submit(recording:String)=p.submitExisting(recording).let{RecordingAnalysisPort.Sent(it.outcome.name,it.jobId)}
        override fun submitBound(recording:String,observer:(LocalJobStore.Job)->Unit)=p.submitExisting(recording,observer).let{RecordingAnalysisPort.Sent(it.outcome.name,it.jobId)}
        override fun poll(job:String)=p.poll(job);override fun pollObservation(job:String)=p.pollObservation(job)
        override fun driveAExport(job:String)=p.driveAExport(job);override fun driveAFrozenRequest(job:String)=p.driveAFrozenRequest(job)
        override fun driveAReopenedReceipt(job:String)=p.driveAReopenedReceipt(job)
        override fun jobs()=p.jobs();override fun retry(job:String):RecordingAnalysisPort.Sent=error("NO_RETRY");override fun cancel(){};override fun close(){}
    }
    private fun submitted(p:GoogleNativePipeline) {
        AnalysisRequestFlow(context,session,{NativePort(p)}).use{f->request=f.prepare(recording,snap());assertEquals("SENT",f.submit(request));assertEquals("SENT",f.submit(request))}
        job=p.jobs().single().id;result=p.jobs().single().resultId;assertEquals(4,drive.counter)
    }
    private fun port(p:GoogleNativePipeline)=ExistingDriveARequestPort(context,session){NativePort(p)}
    private fun candidate(p:GoogleNativePipeline)=DriveAForegroundCandidate(context,port(p))
    private fun frozen()=drive.bytes.values.single {runCatching{StrictJson.`object`(StrictJson.parse(it))["kind"]=="CALL_ANALYSIS_REQUEST"}.getOrDefault(false)}
    private fun proposal(revision:Long=1,raw:String="합성 \"인용\"\nLF 원문 유지입니다.") {
        val r=WireV0Codec.validateRequest(frozen());val sha=DriveRelay.sha256(raw.toByteArray())
        val provenance=mapOf("source_kind" to "synthetic_contract_fixture","language" to "ko","run_id" to "drive_a_host_fixture","audio_sha256" to r["audioSha"],"model_name" to null,"model_sha256" to null,"engine_sha256" to null,"execution_observed" to false,"reference_used_in_inference" to false,"quality_state" to "raw_review_required","run_started_at_utc" to null,"run_finished_at_utc" to null,"runner_sha256" to null,"source_commit" to null,"dataset" to null,"dataset_revision" to null,"license" to null)
        val src=mapOf("source_id" to r["sourceId"],"kind" to "call_transcript","raw_text" to raw,"text_sha256" to sha,"recorded_at" to null,"timestamp_basis" to "unknown","case_id" to null,"case_link_confirmed" to false,"speaker_assignment_verified" to false,"uncertain_ranges" to emptyList<Any>(),"provenance" to provenance)
        val packet=linkedMapOf<String,Any?>("schema_version" to 1L,"job_id" to r["jobId"],"base_revision" to r["baseRevision"],"scope" to "synthetic_contract_test","offset_unit" to "unicode_code_points","automatic_summary_allowed" to false,"root_semantic_review_required" to true,"sources" to listOf(src));packet["source_pack_sha256"]=DriveRelay.sha256(StrictJson.bytes(packet))
        val c=mapOf("schema_version" to 1L,"job_id" to r["jobId"],"base_revision" to r["baseRevision"],"source_pack_sha256" to packet["source_pack_sha256"],"summary" to "합성 후보 · 실제 모델 실행 아님","claims" to emptyList<Any>())
        val value=WireV0Codec.placeholder(r).toMutableMap();value["state"]="PROPOSAL";value["resultRevision"]=revision
        value["stt"]=mapOf("execution" to "FIXTURE","text" to raw,"textSha" to sha,"evidenceRef" to "drive_a_host_fixture_only")
        value["high"]=mapOf("execution" to "FIXTURE","packetJson" to String(StrictJson.bytes(packet)),"candidateJson" to String(StrictJson.bytes(c)),"evidenceRef" to "drive_a_host_fixture_only")
        value["resultDigest"]=WireV0Codec.digest("result",value);drive.bytes[result]=StrictJson.bytes(value);drive.versions[result]=drive.versions.getValue(result)+1
    }
    private fun preserved(note:String="PUBLIC_DRIVE_A_DONE\n\"LF 유지\""){val s=snap();assertEquals("done",s.getString("manual_status"));assertEquals(note,s.getString("manual_text"));assertTrue(s.isNull("effective_summary_version"));assertEquals(0L,count("summary_versions"))}
    private fun proof(id:String,r:DriveAForegroundCandidate.Result?=null) {
        r?.let{assertFalse(it.providerAcceptanceVerified);assertFalse(it.modelExecutionVerified);assertFalse(it.remoteAtomicCasVerified);assertFalse(it.canonicalWriteAllowed)}
        val v=JSONObject().put("id",id).put("pass",true).put("scope","LOCAL_HOST_PRODUCTION_CODE_GENERATED_AUDIO_FAKE_DRIVE_ONLY").put("actualNetworkCalls",0).put("actualModelExecution",0).put("actualDTStatus","NOT_RUN").put("remoteAtomicCas","NOT_VERIFIED").put("nativeDefaultFactoryChanged",false).put("frozenV0WireChanged",false)
        r?.let{v.put("state",it.state).put("handoffIntentCreated",it.handoffIntentCreated)}
        File("build/reports/drive-a-local").apply{mkdirs()}.let{File(it,"$id.json").writeText(v.toString(2))}
    }
    @Test fun D01MetadataExportKeepsExactRequestIdsBytesAndNoRawNetwork()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);source.opens=0;val calls=drive.downloads;val c=candidate(p);val r=c.prepareExplicit(request);assertEquals("REQUEST_PREPARED",r.state);val x=JSONObject(r.export!!.payload);assertEquals(String(frozen()),x.getString("frozenRequestJson"));assertEquals(DriveRelay.sha256(frozen()),x.getString("frozenRequestSha256"));assertFalse(r.export.payload.contains("PUBLIC_FIXTURE_RAM_TOKEN"));assertEquals(0,source.opens);assertEquals(calls,drive.downloads);assertEquals(4,drive.counter);assertEquals(r.export,c.prepareExplicit(request).export);assertEquals(r.export,candidate(p).load(request).export);preserved();proof("D01",r)}}
    @Test fun D02OneHandoffIntentAndCancelledUiNeverAckOrRepeat()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);val first=c.beginHandoffIntentExplicit(request);assertTrue(c.canOpenShareUi(first));val cancelled=c.noteShareUiReturn(request,true);assertEquals("HANDOFF_UNCERTAIN",cancelled.state);val again=candidate(p).beginHandoffIntentExplicit(request);assertFalse(again.handoffIntentCreated);assertFalse(c.canOpenShareUi(again));assertEquals(first.export!!.attempt,again.export!!.attempt);assertEquals(4,drive.counter);assertEquals(0,drive.downloads);proof("D02",cancelled)}}
    @Test fun D03ConcurrentViewsReserveOneUiOffer()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);candidate(p).prepareExplicit(request);val views=coroutineScope{(0..1).map{async(Dispatchers.IO){candidate(p).beginHandoffIntentExplicit(request)}}.awaitAll()};assertEquals(1,views.count{it.handoffIntentCreated});assertEquals(1,views.mapNotNull{it.export?.attempt}.distinct().size);proof("D03")}}
    @Test fun D04UnknownPublicationCannotExportOrResubmit()=runBlocking(Dispatchers.IO){var lost=false;val remote=object:DriveTransport by drive{override fun create(s:DriveTransport.FileSpec,b:ByteArray):DriveTransport.Metadata{val m=drive.create(s,b);if(s.role==DriveTransport.Role.REQUEST&&!lost){lost=true;throw IOException("PUBLIC_LOST_REPLY")};return m}};pipeline(remote).use{p->AnalysisRequestFlow(context,session,{NativePort(p)}).use{f->request=f.prepare(recording,snap());assertEquals("UNKNOWN",f.submit(request));assertEquals("UNKNOWN",f.submit(request))};val r=candidate(p).prepareExplicit(request);assertEquals("REQUEST_NOT_COMMITTED",r.state);assertNull(r.export);assertEquals(4,drive.counter);proof("D04",r)}}
    @Test fun D05MissingGrantDoesNotOpenJournalOrFactory()=runBlocking(Dispatchers.IO){session.localSignOut();var calls=0;val c=DriveAForegroundCandidate(context,ExistingDriveARequestPort(context,session){calls++;error("NO_FACTORY")});val r=c.prepareExplicit("public-request");assertEquals("CURRENT_GRANT_NOT_VERIFIED",r.state);assertEquals(0,calls);assertEquals(0,drive.counter);proof("D05",r)}
    @Test fun D06RestoredSessionCannotImplyCurrentGrant()=runBlocking(Dispatchers.IO){val restored=GoogleConnectionSession(memory);assertNull(DriveALocalScope.current(restored));val r=DriveAForegroundCandidate(context,ExistingDriveARequestPort(context,restored){error("NO_FACTORY")}).load("public-request");assertEquals("CURRENT_GRANT_NOT_VERIFIED",r.state);proof("D06",r)}
    @Test fun D07UnsupportedAccountPreservesNativeCapabilityBeforeRawOrIds()=runBlocking(Dispatchers.IO){source.opens=0;pipeline(capable=false).use{p->AnalysisRequestFlow(context,session,{NativePort(p)}).use{f->request=f.prepare(recording,snap());assertEquals("HELD_CAPABILITY",f.submit(request))};assertEquals(0,source.opens);assertEquals(0,drive.counter);assertFalse(NativeAnalysisAvailability.canTransfer());assertFalse(FrozenDotCapability(context).supports("drive-a@example.invalid"));proof("D07")}}
    @Test fun D08PendingReceiptIsNotExecutedAndErrorIsNotWaiting()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);val pending=c.pollExplicit(request);assertEquals("PENDING",pending.receipt!!.state);assertNull(pending.receipt.raw);drive.failure(result);val failed=c.pollExplicit(request);assertEquals("ERROR",failed.receipt!!.state);assertEquals("ERROR",RecordingWorkflowStore(scoped).use{it.request(request).getString("state")});assertEquals("ERROR",candidate(p).load(request).receipt!!.state);preserved();proof("D08",failed)}}
    @Test fun D09RawLfQuoteAndImmutableResultSurviveReopen()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);proposal();val received=c.pollExplicit(request);val before=drive.downloads;val reopened=candidate(p).load(request);assertEquals("합성 \"인용\"\nLF 원문 유지입니다.",reopened.receipt!!.raw);assertEquals(received.receipt,reopened.receipt);assertEquals(before,drive.downloads);assertEquals("REVIEW",RecordingWorkflowStore(scoped).use{it.request(request).getString("state")});preserved();proof("D09",reopened)}}
    @Test fun D10ManualDoneAfterExportBecomesConflictWithoutReexport()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);GeneralLocalStoreTest.host(scoped,keys).use{it.edit(recording,it.snapshot().getJSONObject(0),"PUBLIC_CHANGED_DONE","done")};proposal();val r=c.pollExplicit(request);assertTrue(r.receipt!!.conflict);assertEquals("RESULT_OBSERVATION_RECORDED",r.state);assertEquals(r.receipt,candidate(p).load(request).receipt);assertNull(c.beginHandoffIntentExplicit(request).export);preserved("PUBLIC_CHANGED_DONE");proof("D10",r)}}
    @Test fun D11ArchivedResultRemainsHiddenAndNoCanonicalWrite()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);GeneralLocalStoreTest.host(scoped,keys).use{it.archive(recording,it.snapshot().getJSONObject(0),true)};proposal();val r=c.pollExplicit(request);assertTrue(r.receipt!!.hidden);assertEquals("RESULT_OBSERVATION_RECORDED",r.state);preserved();proof("D11",r)}}
    @Test fun D12ManualChangeAfterReceiptUsesCurrentConflictWithoutFalseCorruption()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);proposal();assertFalse(c.pollExplicit(request).receipt!!.conflict);GeneralLocalStoreTest.host(scoped,keys).use{it.edit(recording,it.snapshot().getJSONObject(0),"PUBLIC_AFTER_RECEIPT_DONE","done")};val r=candidate(p).load(request);assertEquals("RESULT_OBSERVATION_RECORDED",r.state);assertTrue(r.receipt!!.conflict);preserved("PUBLIC_AFTER_RECEIPT_DONE");proof("D12",r)}}
    @Test fun D13RevokedSelectedGrantBlocksBeforeDownload()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);source.granted=false;source.opens=0;val r=c.pollExplicit(request);assertNull(r.receipt);assertEquals(0,drive.downloads);assertEquals(0,source.opens);proof("D13",r)}}
    @Test fun D14ExpiredLeaseBlocksBeforeDownloadWithoutNewLease()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);primary().use{it.execSQL("UPDATE google_native_leases SET expires_ms=0")};val r=c.pollExplicit(request);assertNull(r.receipt);assertEquals(0,drive.downloads);assertEquals(1L,count("google_native_leases"));proof("D14",r)}}
    @Test fun D15AccountSwitchFencesPreviouslyPreparedShare()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);val r=c.beginHandoffIntentExplicit(request);activate("PUBLIC_OTHER_OWNER");assertFalse(c.canOpenShareUi(r));val late=c.load(request);assertNull(late.export);assertNull(late.receipt);assertEquals(0,drive.downloads);proof("D15",late)}}
    @Test fun D16AccountChangesDuringDownloadCannotCommit()=runBlocking(Dispatchers.IO){val remote=object:DriveTransport by drive{override fun download(id:String,max:Int):DriveTransport.Download{val d=drive.download(id,max);activate("PUBLIC_OTHER_OWNER");return d}};pipeline(remote).use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);proposal();val r=c.pollExplicit(request);assertNull(r.receipt);assertEquals(0L,count("drive_profiles_receipts"));preserved();proof("D16",r)}}
    @Test fun D17StateOnlyReceivedWithoutReceiptIsStoreReviewAndBytesStay()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);val v=c.prepareExplicit(request).export!!;journal().use{it.execSQL("UPDATE a_exports SET state='RESULT_OBSERVATION_RECORDED'")};val r=candidate(p).load(request);assertEquals("STORE_REVIEW",r.state);journal().use{it.rawQuery("SELECT payload FROM a_exports",null).use{q->assertTrue(q.moveToFirst());assertEquals(v.payload,q.getString(0))}};proof("D17",r)}}
    @Test fun D18MissingPreparedReceiptIsStoreReviewWithoutReset()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);journal().use{it.execSQL("DROP TRIGGER a_receipt_no_delete");it.execSQL("DELETE FROM a_receipts WHERE kind='PREPARED'")};val r=c.load(request);assertEquals("STORE_REVIEW",r.state);assertEquals(1L,count("drive_v0_jobs"));assertEquals(4,drive.counter);proof("D18",r)}}
    @Test fun D19ExportShaCorruptionIsStoreReviewNotNewExport()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);journal().use{it.execSQL("DROP TRIGGER a_export_identity");it.execSQL("UPDATE a_exports SET payload_sha='public-corrupt'")};val r=c.prepareExplicit(request);assertEquals("STORE_REVIEW",r.state);assertEquals(4,drive.counter);proof("D19",r)}}
    @Test fun D20PrimaryMissingHeadCannotUseCachedSuccess()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);proposal();c.pollExplicit(request);primary().use{it.execSQL("DELETE FROM drive_profiles_heads")};val r=candidate(p).load(request);assertEquals("STORE_REVIEW",r.state);assertEquals(1L,count("drive_profiles_receipts"));proof("D20",r)}}
    @Test fun D21PrimaryMissingReceiptCannotUseCachedSuccess()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);proposal();c.pollExplicit(request);primary().use{db->db.rawQuery("SELECT name FROM sqlite_master WHERE type='trigger' AND tbl_name='drive_profiles_receipts'",null).use{q->val names=mutableListOf<String>();while(q.moveToNext())names+=q.getString(0);names.forEach{db.execSQL("DROP TRIGGER \"$it\"")}};db.execSQL("DELETE FROM drive_profiles_receipts")};val r=candidate(p).load(request);assertEquals("STORE_REVIEW",r.state);assertEquals(1L,count("drive_v0_jobs"));proof("D21",r)}}
    @Test fun D22MalformedCachedObservationCannotBeDisplayed()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);proposal();c.pollExplicit(request);journal().use{db->val value=db.rawQuery("SELECT payload FROM a_receipts WHERE kind='RESULT_OBSERVATION'",null).use{q->q.moveToFirst();StrictJson.`object`(StrictJson.parse(q.getString(0).toByteArray())).toMutableMap()};value["unexpected"]=true;val bytes=StrictJson.bytes(value);db.execSQL("DROP TRIGGER a_receipt_no_update");db.execSQL("UPDATE a_receipts SET payload=?,digest=? WHERE kind='RESULT_OBSERVATION'",arrayOf(String(bytes),DriveRelay.sha256(bytes)))};val r=c.load(request);assertEquals("STORE_REVIEW",r.state);assertEquals(1L,count("drive_profiles_receipts"));proof("D22",r)}}
    @Test fun D23JournalReceiptUpdateDeleteReplaceAreRejected()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);candidate(p).prepareExplicit(request);journal().use{db->for(sql in listOf("UPDATE a_receipts SET payload='public-change'","DELETE FROM a_receipts","INSERT OR REPLACE INTO a_receipts SELECT * FROM a_receipts","INSERT OR REPLACE INTO a_exports SELECT * FROM a_exports")){try{db.execSQL(sql);fail(sql)}catch(_:android.database.sqlite.SQLiteException){}}};assertEquals("REQUEST_PREPARED",candidate(p).load(request).state);proof("D23")}}
    private fun metadata(m:DriveTransport.Metadata,version:String?=m.version,size:Long=m.size,id:String=m.id)=DriveTransport.Metadata(id,m.parentId,m.name,m.mimeType,m.ownerBinding,version,m.trashed,m.isAppAuthorized,m.privateToOwner,size)
    @Test fun D24AbsentVersionBeforeReadBlocksDownload()=runBlocking(Dispatchers.IO){val remote=object:DriveTransport by drive{override fun metadata(id:String):DriveTransport.Metadata{val m=drive.metadata(id);return if(m.mimeType==DriveTransport.JSON_MIME)metadata(m,version=null)else m}};pipeline(remote).use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);val r=c.pollExplicit(request);assertNull(r.receipt);assertEquals(0,drive.downloads);assertEquals(0L,count("drive_profiles_receipts"));proof("D24",r)}}
