    @Test fun D30OlderHistoryCannotLowerGlobalHeadOrJournalView()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);val pending=drive.bytes.getValue(result).clone();c.pollExplicit(request);drive.failure(result);c.pollExplicit(request);proposal(2);val current=c.pollExplicit(request);drive.bytes[result]=pending;drive.versions[result]=drive.versions.getValue(result)+1;val old=c.pollExplicit(request);assertEquals(2L,old.receipt!!.revision);assertEquals(current.receipt,old.receipt);assertEquals(3L,count("drive_profiles_receipts"));assertEquals("REVIEW",RecordingWorkflowStore(scoped).use{it.request(request).getString("state")});proof("D30",old)}}
    @Test fun D31SameRevisionDifferentDigestIsQuarantinedWithCurrentReceiptKept()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);proposal();val first=c.pollExplicit(request);proposal(1,"PUBLIC_DIFFERENT_SAME_REV");val r=c.pollExplicit(request);assertEquals(first.receipt,r.receipt);assertEquals(1L,count("drive_profiles_collisions"));assertEquals(1L,count("drive_profiles_receipts"));preserved();proof("D31",r)}}
    @Test fun D32UnknownProfileCannotBeMisdecodedAsV0()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);val x=StrictJson.`object`(StrictJson.parse(drive.bytes.getValue(result))).toMutableMap();x["kind"]="PUBLIC_UNSUPPORTED_PROFILE";x["schemaVersion"]=1L;drive.bytes[result]=StrictJson.bytes(x);val r=c.pollExplicit(request);assertNull(r.receipt);assertEquals(0L,count("drive_profiles_receipts"));proof("D32",r)}}
    @Test fun D33LocalDiagnosticsDoNotAssertCurrentRegistrationGrantWriterOrCas()=runBlocking(Dispatchers.IO){val d=DriveADeviceDiagnostics.inspect(context);for(k in listOf("currentConsolePackageSha1Match","actualS25InstalledIdentity","currentDeviceGrant","dotConnectorExactFileAccessAndWriter","writerProvenance","remoteAtomicCas"))assertEquals("NOT_VERIFIED",d.getString(k));assertFalse(d.getBoolean("credentialsIncluded"));assertFalse(d.getBoolean("newPermissionRequested"));proof("D33")}
    @Test fun D34FractionalHeadRevisionCannotBeTruncatedIntoSuccess()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);proposal();c.pollExplicit(request);primary().use{it.execSQL("UPDATE drive_profiles_heads SET result_revision=1.5")};val r=candidate(p).load(request);assertEquals("STORE_REVIEW",r.state);assertEquals(1L,count("drive_profiles_receipts"));proof("D34",r)}}
    @Test fun D35FractionalJobCursorCannotBeTruncatedOrRepairedByPoll()=runBlocking(Dispatchers.IO){pipeline().use{p->submitted(p);val c=candidate(p);c.prepareExplicit(request);proposal();c.pollExplicit(request);val before=drive.downloads;primary().use{it.execSQL("UPDATE drive_v0_jobs SET result_revision=1.5")};val r=candidate(p).pollExplicit(request);assertEquals("STORE_REVIEW",r.state);assertEquals(before,drive.downloads);primary().use{it.rawQuery("SELECT result_revision FROM drive_v0_jobs",null).use{q->q.moveToFirst();assertEquals(android.database.Cursor.FIELD_TYPE_FLOAT,q.getType(0));assertEquals(1.5,q.getDouble(0),0.0)}};proof("D35",r)}}

